The issue is that the method `TestMax` is missing its body - the body appears at the end of the file disconnected from the method declaration.

@@ method TestMax(a: int, b: int)
- method TestMax(a: int, b: int)
+ method TestMax(a: int, b: int)
+ {
+   var result := Max(a, b);
+   assert result == a || result == b;
+   assert result >= a && result >= b;
+ }
@@ {
-  {
-   var result := Max(a, b);
-   assert result == a || result == b;
-   assert result >= a && result >= b;
- }
